/// TMDB API client generated by spargen from the OpenAPI 3.1 spec.
///
/// This module holds the generated client, its typed models (`types`), its
/// error taxonomy, and the runtime support code spargen embeds in its output
/// (no spargen crate is a dependency).
///
/// The generated code is **vendored** in `src/generated/tmdb.rs` and committed
/// to the repository — it is not regenerated during a normal `cargo build`. To
/// regenerate it after changing `openapi/tmdb-api.json`, run `cargo xtask
/// codegen` (see `DEVELOPMENT.md`). Do not edit `tmdb.rs` by hand.
#[allow(
    clippy::all,
    clippy::pedantic,
    missing_docs,
    unused_imports,
    unreachable_code,
    unreachable_patterns
)]
pub mod tmdb {
    include!("tmdb.rs");
}
